-- 기반 클래스를 바꿔 끼운다

public class BaseRepositoryImpl<T, ID>
        extends SimpleJpaRepository<T, ID> {

    private final EntityManager em;

    public BaseRepositoryImpl(JpaEntityInformation<T, ?> info,
                              EntityManager em) {
        super(info, em);
        this.em = em;
    }

    public void flushAndClear() {
        em.flush();
        em.clear();
    }
}

@EnableJpaRepositories(repositoryBaseClass = BaseRepositoryImpl.class)

@Test
void 바꿔_끼움() throws Exception {
    Object t = ((Advised) memberRepository).getTargetSource().getTarget();
    System.out.println("대상: " + t.getClass().getSimpleName());
